// Nodo "Configuración" — EDITÁ ESTOS VALORES.
const DESTINATARIO = 'tu.mail@pepsico.com';           // a quién le llega el resumen (podés poner varios separados por coma)
const LINK_DASHBOARD = '';                              // pegá acá el link del dashboard cuando lo publiques
const UMBRAL_VARIACION_PCT = 1;                         // cambios de precio menores a este % no se reportan

const fecha = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Argentina/Buenos_Aires' }).format(new Date());
return [{ json: { fecha, destinatario: DESTINATARIO, link_dashboard: LINK_DASHBOARD, umbral: UMBRAL_VARIACION_PCT } }];

// Nodo "Pedido a Claude" — resume los cambios del día para que Claude escriba el análisis.
let r = $input.first().json.r;
if (typeof r === 'string') r = JSON.parse(r);
const al = r.alertas || [];
const top = (tipo, n = 12) => al.filter((a) => a.tipo === tipo).slice(0, n)
  .map((a) => `${a.retailer} · ${a.nombre} · ${a.precio_anterior ?? '-'} → ${a.precio_nuevo ?? '-'}${a.variacion_pct != null ? ` (${a.variacion_pct}%)` : ''}${a.detalle ? ` · ${a.detalle}` : ''}`)
  .join('\n') || '(ninguno)';

const datos = `Fecha: ${r.fecha} (comparado contra ${r.fecha_anterior || 'sin captura previa'})
SKUs relevados: ${r.skus} · Registros: ${r.registros}
Cantidad de cambios: ${JSON.stringify(r.conteo)}
Por cadena: ${JSON.stringify(r.por_retailer)}
Índice de precios (100 = mediana del mercado; menor = más barato): ${JSON.stringify(r.indice)}

SUBAS:
${top('suba')}

BAJAS:
${top('baja')}

PROMOS NUEVAS:
${top('promo_nueva')}

PROMOS QUE TERMINARON:
${top('promo_fin')}

QUIEBRES / DESAPARECIDOS:
${top('quiebre')}

SKUs NUEVOS:
${top('nuevo_sku')}`;

const sistema = `Sos analista de pricing y shopper marketing de PepsiCo Argentina (snacks: Lay's, Doritos, 3D, Cheetos, Tostitos, Twistos, Pehuamar) en el canal supermercados online.
Escribí el resumen ejecutivo del día en español rioplatense, profesional y directo.
Reglas:
- Entre 3 y 6 bullets. Cada bullet con cifras concretas tomadas de los datos (cadena, producto, % y precio).
- Priorizá: movimientos de precio relevantes, cadenas que se desalinean del resto, promos de la competencia entre cadenas, quiebres de stock que afectan venta.
- Si no hay captura anterior, decilo y describí la foto del día (cadena más barata/cara según el índice, % de SKUs en promo).
- Si hay 0 registros, avisá que la recolección falló y no analices nada más.
- NO inventes datos ni causas que no estén en la información.
- Devolvé SOLO HTML: un <ul> con <li>. Podés usar <b>. Nada más.`;

return [{ json: {
  body: {
    model: 'claude-sonnet-5-5',
    max_tokens: 1200,
    system: sistema,
    messages: [{ role: 'user', content: datos }],
  },
} }];

// Nodo "Armar mail" — HTML compatible con Outlook (tablas y estilos inline).
const cfg = $('Configuración').first().json;
let r = $('Resumen del día').first().json.r;
if (typeof r === 'string') r = JSON.parse(r);
const ia = $input.first().json || {};

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const pesos = (n) => (n == null || n === '' ? '—' : '$' + Number(n).toLocaleString('es-AR', { maximumFractionDigits: 0 }));
const pct = (n) => (n == null ? '' : (n > 0 ? '+' : '') + Number(n).toLocaleString('es-AR', { maximumFractionDigits: 1 }) + '%');
const fechaLarga = (f) => new Date(f + 'T12:00:00').toLocaleDateString('es-AR', { weekday: 'long', day: 'numeric', month: 'long' });

// Texto de Claude: sólo dejamos <ul>, <li>, <b>, <strong>
let analisis = (ia.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('').trim();
analisis = analisis.replace(/```html?|```/g, '').replace(/<(?!\/?(ul|li|b|strong)\b)[^>]*>/gi, '');
if (!/<li/i.test(analisis)) analisis = analisis ? `<p>${esc(analisis)}</p>` : '<p style="color:#898781">(El análisis automático no estuvo disponible hoy; abajo están todos los cambios.)</p>';

const al = r.alertas || [];
const c = r.conteo || {};
const MAX = 25;

function tabla(titulo, color, filas, columnas) {
  if (!filas.length) return '';
  const extra = filas.length > MAX ? `<p style="margin:6px 0 0;font-size:12px;color:#898781">…y ${filas.length - MAX} más (ver dashboard).</p>` : '';
  return `
  <h3 style="margin:28px 0 8px;font-size:15px;color:#0b0b0b;border-left:4px solid ${color};padding-left:8px">${titulo} <span style="color:#898781;font-weight:normal">(${filas.length})</span></h3>
  <table cellpadding="0" cellspacing="0" width="100%" style="border-collapse:collapse;font-size:13px">
    <tr>${columnas.map((col) => `<th align="${col.a || 'left'}" style="padding:6px 8px;border-bottom:1px solid #c3c2b7;color:#52514e;font-weight:600">${col.t}</th>`).join('')}</tr>
    ${filas.slice(0, MAX).map((f) => `<tr>${columnas.map((col) => `<td align="${col.a || 'left'}" style="padding:6px 8px;border-bottom:1px solid #e1e0d9">${col.v(f)}</td>`).join('')}</tr>`).join('')}
  </table>${extra}`;
}

const colsPrecio = [
  { t: 'Cadena', v: (a) => esc(a.retailer) },
  { t: 'Producto', v: (a) => esc(a.nombre) },
  { t: 'Antes', a: 'right', v: (a) => pesos(a.precio_anterior) },
  { t: 'Hoy', a: 'right', v: (a) => `<b>${pesos(a.precio_nuevo)}</b>` },
  { t: 'Var.', a: 'right', v: (a) => `<b style="color:${a.variacion_pct > 0 ? '#d03b3b' : '#006300'}">${pct(a.variacion_pct)}</b>` },
];
const colsPromo = [
  { t: 'Cadena', v: (a) => esc(a.retailer) },
  { t: 'Producto', v: (a) => esc(a.nombre) },
  { t: 'Precio', a: 'right', v: (a) => pesos(a.precio_nuevo) },
  { t: 'Promo', v: (a) => esc(a.detalle || '') },
];
const colsSimple = [
  { t: 'Cadena', v: (a) => esc(a.retailer) },
  { t: 'Producto', v: (a) => esc(a.nombre) },
  { t: 'Detalle', v: (a) => esc(a.detalle || '') },
];
const de = (t) => al.filter((a) => a.tipo === t);

const kpi = (valor, etiqueta) => `<td align="center" style="padding:12px 6px;background:#f9f9f7;border:1px solid #e1e0d9;border-radius:6px">
  <div style="font-size:22px;font-weight:700;color:#0b0b0b">${valor}</div>
  <div style="font-size:11px;color:#52514e;text-transform:uppercase;letter-spacing:.04em">${etiqueta}</div></td>`;

const indice = (r.indice || []).map((x) => `<tr><td style="padding:4px 8px">${esc(x.retailer)}</td>
  <td align="right" style="padding:4px 8px;font-weight:600;color:${x.indice <= 98 ? '#006300' : x.indice >= 102 ? '#d03b3b' : '#0b0b0b'}">${Number(x.indice).toFixed(1)}</td>
  <td align="right" style="padding:4px 8px;color:#898781">${x.skus_comparables} SKUs</td></tr>`).join('');

const sinDatos = !r.registros;
const total = al.length;

const html = `<!doctype html><html><body style="margin:0;background:#f4f4f2">
<table width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f2;padding:24px 0"><tr><td align="center">
<table width="680" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:10px;padding:28px;font-family:Segoe UI,Arial,sans-serif;color:#0b0b0b">
<tr><td>
  <div style="font-size:12px;color:#52514e;text-transform:uppercase;letter-spacing:.06em">Monitor de precios · Snacks PepsiCo</div>
  <h1 style="margin:4px 0 2px;font-size:22px">Cambios del ${esc(fechaLarga(r.fecha))}</h1>
  <div style="font-size:13px;color:#52514e">${r.fecha_anterior ? `Comparado contra la captura del ${esc(r.fecha_anterior)}` : 'Primera captura: todavía no hay día anterior para comparar.'}</div>

  ${sinDatos ? `<p style="margin:18px 0;padding:12px;background:#fdecec;border-left:4px solid #d03b3b">⚠ Hoy no se registraron precios. Revisá la última ejecución del workflow <b>1 · Recolector</b> en n8n.</p>` : `
  <table width="100%" cellpadding="0" cellspacing="6" style="margin:18px 0 4px"><tr>
    ${kpi(r.skus, 'SKUs relevados')}
    ${kpi((c.suba || 0) + (c.baja || 0), 'Cambios de precio')}
    ${kpi(c.promo_nueva || 0, 'Promos nuevas')}
    ${kpi(c.quiebre || 0, 'Quiebres')}
  </tr></table>`}

  <h3 style="margin:24px 0 6px;font-size:15px">Lo importante</h3>
  <div style="font-size:14px;line-height:1.5">${analisis}</div>

  ${!sinDatos && total === 0 && r.fecha_anterior ? '<p style="color:#52514e">Sin cambios relevantes respecto del día anterior.</p>' : ''}
  ${tabla('Subas de precio', '#d03b3b', de('suba'), colsPrecio)}
  ${tabla('Bajas de precio', '#0ca30c', de('baja'), colsPrecio)}
  ${tabla('Promos nuevas', '#2a78d6', de('promo_nueva'), colsPromo)}
  ${tabla('Quiebres de stock / productos que desaparecieron', '#fab219', de('quiebre'), colsSimple)}
  ${tabla('Reposiciones', '#1baf7a', de('reposicion'), colsSimple)}
  ${tabla('Promos que terminaron', '#898781', de('promo_fin'), colsSimple)}
  ${tabla('SKUs nuevos en góndola online', '#6250d6', de('nuevo_sku'), colsPromo)}

  ${indice ? `<h3 style="margin:28px 0 8px;font-size:15px">Índice de precios por cadena</h3>
  <div style="font-size:12px;color:#52514e;margin-bottom:6px">100 = mediana del mercado para el mismo producto. Menos de 100 = más barato que el resto.</div>
  <table cellpadding="0" cellspacing="0" style="font-size:13px">${indice}</table>` : ''}

  ${cfg.link_dashboard ? `<p style="margin:28px 0 0"><a href="${esc(cfg.link_dashboard)}" style="background:#2a78d6;color:#fff;padding:10px 16px;border-radius:6px;text-decoration:none;font-weight:600">Abrir dashboard</a></p>` : ''}
  <p style="margin:28px 0 0;font-size:11px;color:#898781">Precios públicos de las tiendas online de Carrefour, Jumbo, Disco, Vea, Día, ChangoMás y Coto. Generado automáticamente por n8n + Claude.</p>
</td></tr></table></td></tr></table></body></html>`;

const asunto = sinDatos
  ? `⚠ Monitor de precios ${r.fecha}: sin datos hoy`
  : `Precios snacks ${r.fecha}: ${(c.suba || 0)} subas · ${(c.baja || 0)} bajas · ${(c.promo_nueva || 0)} promos · ${(c.quiebre || 0)} quiebres`;

return [{ json: { destinatario: cfg.destinatario, asunto, html } }];
